using System.Runtime.InteropServices;

namespace MicroEngine.NativeChecks;

/// <summary>
/// Key and pointer events generated by the X server itself (the XTEST extension), as a physical keyboard and mouse
/// would produce them, for the native keyboard tests of every desktop backend. Shared by the raylib and SDL tests
/// (linked into MicroEngine.Desktop.Tests).
/// </summary>
internal sealed partial class XTest : IDisposable
{
    public const nint XkSpace = 0x20, XkLeft = 0xff51;

    [LibraryImport("libX11.so.6")] private static partial nint XOpenDisplay(nint name);
    [LibraryImport("libX11.so.6")] private static partial int XCloseDisplay(nint display);
    [LibraryImport("libX11.so.6")] private static partial byte XKeysymToKeycode(nint display, nint keysym);
    [LibraryImport("libX11.so.6")] private static partial int XSync(nint display, int discard);
    [LibraryImport("libXtst.so.6")] private static partial int XTestQueryExtension(nint display, out int eventBase, out int errorBase, out int major, out int minor);
    [LibraryImport("libXtst.so.6")] private static partial int XTestFakeKeyEvent(nint display, uint keycode, int isPress, nuint delay);
    [LibraryImport("libXtst.so.6")] private static partial int XTestFakeMotionEvent(nint display, int screen, int x, int y, nuint delay);

    private readonly nint _display;

    private XTest(nint display) => _display = display;

    /// <summary>Connects to the X display; null and the reason when there is none or it lacks XTEST.</summary>
    public static XTest? Open(out string missing)
    {
        missing = "";
        if (string.IsNullOrEmpty(Environment.GetEnvironmentVariable("DISPLAY"))) { missing = "No X display (run under xvfb-run)."; return null; }
        nint display;
        try { display = XOpenDisplay(0); }
        catch (DllNotFoundException e) { missing = $"libX11/libXtst missing: {e.Message}"; return null; }
        if (display == 0) { missing = "Cannot open the X display."; return null; }
        if (XTestQueryExtension(display, out _, out _, out _, out _) == 0)
        {
            XCloseDisplay(display);
            missing = "The X server has no XTEST extension.";
            return null;
        }
        return new XTest(display);
    }

    /// <summary>
    /// Moves the pointer to a screen position: with no window manager (Xvfb), keyboard focus follows the pointer, so
    /// the pointer is moved over a window before any key is sent to it.
    /// </summary>
    public void MovePointer(int x, int y)
    {
        XTestFakeMotionEvent(_display, -1, x, y, 0);
        XSync(_display, 0);
    }

    /// <summary>Presses or releases the key of an X keysym (<see cref="XkSpace"/>, <see cref="XkLeft"/>).</summary>
    public void Key(nint keysym, bool press)
    {
        XTestFakeKeyEvent(_display, XKeysymToKeycode(_display, keysym), press ? 1 : 0, 0);
        XSync(_display, 0);
    }

    public void Dispose() => XCloseDisplay(_display);
}
